import sys

def parse_price(price_str):
    if '.' in price_str:
        dollars, cents = price_str.split('.')
        cents = cents.zfill(2)
    else:
        dollars, cents = price_str, '00'
    dollars = dollars.replace('.', '')
    return int(dollars), int(cents)

def format_price(total_cents):
    total_dollars, cents = divmod(total_cents, 100)
    dollars_str = str(total_dollars)
    formatted_dollars = '.'.join([dollars_str[max(0, i-3):i] for i in range(len(dollars_str), 0, -3)])[::-1]
    return f"{formatted_dollars}.{cents:02}"

def calculate_total_price(bill):
    import re
    items = re.findall(r'[a-z]+(\d+(\.\d{1,2})?)', bill)
    total_cents = sum(parse_price(price)[0] * 100 + parse_price(price)[1] for _, price in items)
    return format_price(total_cents)

bill = sys.stdin.read().strip()
print(calculate_total_price(bill))
